//! The licence texts that come with `fanrgb.exe` (Settings › About › Licences).
//!
//! Someone who only has the exe must still receive every notice and licence it carries: FanRGB's NOTICE and
//! its own licences (Apache-2.0, and MPL-2.0 for two files), the LGPL-2.1 of the embedded PawnIO modules,
//! the font and HIDAPI licences (`licenses/`, Inter's OFL in `assets/fonts`), and the licences of the Rust
//! crates compiled in (`THIRD-PARTY-LICENSES.txt`, generated by cargo-about from `about-text.hbs`; see
//! docs/RELEASING.md, "Licences"). Releases attach the same files (`tools/release.ps1`).

use super::fonts::OFL_TEXT;

pub const NOTICE: &str = include_str!("../../NOTICE");
pub const APACHE_2_0: &str = include_str!("../../LICENSE");
pub const MPL_2_0: &str = include_str!("../../LICENSE-MPL-2.0");
pub const LGPL_2_1: &str = include_str!("../../assets/pawnio/COPYING");
pub const RUST_CRATES: &str = include_str!("../../THIRD-PARTY-LICENSES.txt");
pub const HACK: &str = include_str!("../../licenses/Hack.txt");
pub const NOTO_EMOJI: &str = include_str!("../../licenses/NotoEmoji-OFL.txt");
pub const UBUNTU_FONT: &str = include_str!("../../licenses/Ubuntu-Font-Licence.txt");
pub const EMOJI_ICON_FONT: &str = include_str!("../../licenses/emoji-icon-font-MIT.txt");
/// HIDAPI's choice of licences, then the BSD-style one FanRGB uses.
pub const HIDAPI: &str = concat!(
    include_str!("../../licenses/hidapi-LICENSE.txt"),
    "\n--------------------------------------------------------------------------------\n\n",
    include_str!("../../licenses/hidapi-BSD.txt")
);

/// Where the source code of what a licence covers is published.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Source {
    /// FanRGB's own repository ([`crate::updater::REPO`]).
    Repo,
    Url(&'static str),
}

/// One document of the Licences dialog.
#[derive(Debug)]
pub struct Doc {
    /// Short name for the picker.
    pub label: &'static str,
    /// What the text covers. Ends with "is at:" when [`Doc::source`] is set: the URL follows.
    pub covers: &'static str,
    pub text: &'static str,
    pub source: Option<Source>,
}

/// `https://github.com/<owner>/<name>` of FanRGB's repository.
pub fn repo_url() -> String {
    format!("https://github.com/{}", crate::updater::REPO)
}

impl Doc {
    pub fn source_url(&self) -> Option<String> {
        self.source.map(|s| match s {
            Source::Repo => repo_url(),
            Source::Url(u) => u.to_string(),
        })
    }

    /// The line shown above the text: what it covers and, where it applies, where the source code is.
    pub fn note(&self) -> String {
        match self.source_url() {
            Some(url) => format!("{} {url}", self.covers),
            None => self.covers.to_string(),
        }
    }
}

