/// Splits `text` into display lines of at most `cols` characters, for a monospace view: carriage returns
/// dropped, tabs as four spaces, a long line broken at the last space that fits (hard, where there is
/// none). Blank lines stay blank; a final newline does not add an empty line.
pub fn wrap_lines(text: &str, cols: usize) -> Vec<String> {
    let cols = cols.max(1);
    let mut out = Vec::new();
    let text = text.strip_suffix('\n').unwrap_or(text);
    for raw in text.split('\n') {
        let line: Vec<char> = raw.strip_suffix('\r').unwrap_or(raw).replace('\t', "    ").chars().collect();
        let mut rest = &line[..];
        while rest.len() > cols {
            // A space within the first `cols + 1` characters that has text before it (not indentation).
            let cut = rest[..=cols].iter().rposition(|&c| c == ' ').filter(|&i| rest[..i].iter().any(|&c| c != ' '));
            match cut {
                Some(i) => {
                    out.push(rest[..i].iter().collect::<String>().trim_end().to_string());
                    rest = &rest[i + 1..];
                }
                None => {
                    out.push(rest[..cols].iter().collect());
                    rest = &rest[cols..];
                }
            }
        }
        out.push(rest.iter().collect());
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Each embedded text is there and is the licence it says it is.
    #[test]
    fn embedded_licence_texts_are_complete() {
        let names: [(&str, &[&str]); 11] = [
            ("Notice", &["FanRGB", "Apache License, Version 2.0", "Mozilla Public License, Version 2.0"]),
            ("Apache-2.0", &["Apache License", "Version 2.0, January 2004"]),
            ("MPL-2.0", &["Mozilla Public License Version 2.0"]),
            ("LGPL-2.1", &["GNU LESSER GENERAL PUBLIC LICENSE", "Version 2.1, February 1999"]),
            (
                "Rust crates",
                &["Rust crates compiled into fanrgb.exe", "Apache License 2.0", "MIT License", "egui 0.33"],
            ),
            ("Inter", &["SIL Open Font License", "Inter Project Authors"]),
            ("Hack", &["MIT License", "Bitstream Vera License"]),
            ("Noto Emoji", &["SIL Open Font License", "Noto Emoji"]),
            ("Ubuntu font", &["UBUNTU FONT LICENCE Version 1.0"]),
            ("emoji-icon-font", &["MIT License", "John Slegers"]),
            ("HIDAPI", &["HIDAPI can be used under one of three licenses", "Alan Ott", "BSD", "Redistribution"]),
        ];
        assert_eq!(DOCS.len(), names.len());
        for (doc, (label, needles)) in DOCS.iter().zip(names) {
            assert_eq!(doc.label, label);
            assert!(!doc.text.trim().is_empty(), "{label} is empty");
            assert!(!doc.covers.is_empty(), "{label}");
            for n in needles {
                assert!(doc.text.contains(n), "{label} does not contain {n:?}");
            }
        }
    }

    /// Every file in licenses/ is embedded (a new one cannot be forgotten).
    #[test]
    fn every_file_in_licenses_is_embedded() {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("licenses");
        let mut n = 0;
        for e in std::fs::read_dir(&dir).unwrap() {
            let path = e.unwrap().path();
            let text = std::fs::read_to_string(&path).unwrap();
            assert!(DOCS.iter().any(|d| d.text.contains(text.trim())), "{} is not shown", path.display());
            n += 1;
        }
        assert!(n >= 6, "{n} files in {}", dir.display());
    }

    /// The MPL-2.0 text says where the source code is: FanRGB's repository, from `updater::REPO`.
    #[test]
    fn mpl_note_names_the_source_repository() {
        let mpl = DOCS.iter().find(|d| d.label == "MPL-2.0").unwrap();
        let note = mpl.note();
        assert!(note.contains("src/hw/superio/ite.rs") && note.contains("src/hw/superio/mod.rs"), "{note}");
        assert!(note.ends_with(&format!("is at: https://github.com/{}", crate::updater::REPO)), "{note}");
        let lgpl = DOCS.iter().find(|d| d.label == "LGPL-2.1").unwrap().note();
        assert!(lgpl.ends_with("is at: https://github.com/namazso/PawnIO.Modules/releases/tag/0.2.11"), "{lgpl}");
        for d in &DOCS {
            assert_eq!(d.covers.ends_with("is at:"), d.source.is_some(), "{}", d.label);
        }
    }

    /// THIRD-PARTY-LICENSES.txt lists crate versions that are in Cargo.lock: a dependency update without
    /// regenerating it fails here (docs/RELEASING.md, "Licences").
    #[test]
    fn crate_licences_match_cargo_lock() {
        let lock = include_str!("../../Cargo.lock").replace('\r', "");
        let mut listed = 0;
        let mut in_used_by = false;
        for line in RUST_CRATES.lines().map(|l| l.trim_end_matches('\r')) {
            if line == "Used by:" {
                in_used_by = true;
                continue;
            }
            if !in_used_by {
                continue;
            }
            let Some(entry) = line.strip_prefix("  ") else {
                in_used_by = false;
                continue;
            };
            let mut parts = entry.split(' ');
            let (name, version) = (parts.next().unwrap(), parts.next().unwrap());
            let needle = format!("name = \"{name}\"\nversion = \"{version}\"\n");
            assert!(
                lock.contains(&needle),
                "{name} {version} is not in Cargo.lock: regenerate THIRD-PARTY-LICENSES.txt"
            );
            listed += 1;
        }
        assert!(listed > 100, "only {listed} crates listed");
    }

    // Independent tests (2026-11-06), written separately from the change itself.

    fn repo_file(rel: &str) -> Vec<u8> {
        let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(rel);
        std::fs::read(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display()))
    }

    fn doc(label: &str) -> &'static Doc {
        DOCS.iter().find(|d| d.label == label).unwrap_or_else(|| panic!("no document {label}"))
    }

    /// Each document is its file on disk, byte for byte: no stale copy, no wrong file behind a label.
    /// HIDAPI is its two files, each whole, in order.
    #[test]
    fn tester_documents_are_the_files_on_disk() {
        for (label, file) in [
            ("Notice", "NOTICE"),
            ("Apache-2.0", "LICENSE"),
            ("MPL-2.0", "LICENSE-MPL-2.0"),
            ("LGPL-2.1", "assets/pawnio/COPYING"),
            ("Rust crates", "THIRD-PARTY-LICENSES.txt"),
            ("Inter", "assets/fonts/OFL.txt"),
            ("Hack", "licenses/Hack.txt"),
            ("Noto Emoji", "licenses/NotoEmoji-OFL.txt"),
            ("Ubuntu font", "licenses/Ubuntu-Font-Licence.txt"),
            ("emoji-icon-font", "licenses/emoji-icon-font-MIT.txt"),
        ] {
            assert!(doc(label).text.as_bytes() == repo_file(file).as_slice(), "{label} is not {file} byte for byte");
        }
        let h = doc("HIDAPI").text.as_bytes();
        let (a, b) = (repo_file("licenses/hidapi-LICENSE.txt"), repo_file("licenses/hidapi-BSD.txt"));
        assert!(h.starts_with(&a) && h.ends_with(&b) && h.len() > a.len() + b.len(), "HIDAPI");
    }

    /// Every licence file NOTICE refers to exists and is shown whole, and every file in `licenses/` is one
    /// NOTICE refers to (so NOTICE, the folder and the dialog cannot drift apart).
    #[test]
    fn tester_notice_and_licenses_folder_agree_with_the_dialog() {
        let mut named = std::collections::BTreeSet::new();
        for raw in NOTICE.split(|c: char| c.is_whitespace() || "(),;".contains(c)) {
            let t = raw.trim_end_matches(['.', ':']);
            let licence_file = t.starts_with("licenses/")
                || t.starts_with("LICENSE")
                || t.starts_with("THIRD-PARTY-LICENSES")
                || t == "assets/pawnio/COPYING"
                || t == "assets/fonts/OFL.txt";
            if licence_file {
                named.insert(t.to_string());
            }
        }
        for must in [
            "LICENSE",
            "LICENSE-MPL-2.0",
            "assets/pawnio/COPYING",
            "assets/fonts/OFL.txt",
            "THIRD-PARTY-LICENSES.txt",
            "THIRD-PARTY-LICENSES.html",
        ] {
            assert!(named.contains(must), "NOTICE does not name {must}: {named:?}");
        }
        for f in &named {
            let bytes = repo_file(f);
            assert!(!bytes.is_empty(), "{f} is empty");
            if f.ends_with(".html") {
                continue; // the HTML rendering of THIRD-PARTY-LICENSES.txt; releases attach it
            }
            let text = String::from_utf8(bytes).unwrap();
            assert!(DOCS.iter().any(|d| d.text.contains(&text)), "{f} (named in NOTICE) is not shown whole");
        }
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("licenses");
        for e in std::fs::read_dir(&dir).unwrap() {
            let name = e.unwrap().file_name().into_string().unwrap();
            assert!(named.contains(&format!("licenses/{name}")), "licenses/{name} is not named in NOTICE");
        }
    }

    /// THIRD-PARTY-LICENSES.txt lists exactly the crates compiled in: the normal-dependency tree of fanrgb
    /// for x86_64-pc-windows-msvc with the features a build uses (`cargo tree`; `cargo metadata` is not
    /// feature-exact and lists optional crates that are never built). `crate_licences_match_cargo_lock`
    /// only checks that the listed crates are in Cargo.lock, so a crate added without regenerating the file
    /// passes it; this one does not.
    #[test]
    fn tester_every_compiled_crate_is_listed() {
        use std::collections::BTreeSet;
        let manifest = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("Cargo.toml");
        let cargo = std::env::var("CARGO").unwrap_or_else(|_| "cargo".into());
        let out = std::process::Command::new(cargo)
            .args(["tree", "--locked", "--offline", "-e", "normal", "--prefix", "none"])
            .args(["--target", "x86_64-pc-windows-msvc", "--manifest-path"])
            .arg(&manifest)
            .output()
            .unwrap();
        assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
        let compiled: BTreeSet<String> = String::from_utf8(out.stdout)
            .unwrap()
            .lines()
            .filter_map(|l| {
                let mut p = l.split(' ');
                Some(format!("{} {}", p.next()?, p.next()?.strip_prefix('v')?))
            })
            .filter(|nv| !nv.starts_with("fanrgb "))
            .collect();
        // "Used by:" lines: two spaces, the crate name, its version, then optionally "(<repository>)".
        let listed: BTreeSet<String> = RUST_CRATES
            .lines()
            .filter_map(|l| l.strip_prefix("  "))
            .filter_map(|l| {
                let mut p = l.trim_end_matches('\r').split(' ');
                let (name, version) = (p.next()?, p.next()?);
                let name_ok = !name.is_empty() && name.bytes().all(|b| b.is_ascii_alphanumeric() || b"-_".contains(&b));
                let version_ok = version.starts_with(|c: char| c.is_ascii_digit()) && version.contains('.');
                (name_ok && version_ok).then(|| format!("{name} {version}"))
            })
            .collect();
        assert!(compiled.len() > 100, "{} crates", compiled.len());
        let missing: Vec<_> = compiled.difference(&listed).collect();
        assert!(missing.is_empty(), "compiled in but not in THIRD-PARTY-LICENSES.txt: {missing:?}");
        let extra: Vec<_> = listed.difference(&compiled).collect();
        assert!(extra.is_empty(), "in THIRD-PARTY-LICENSES.txt but not compiled in: {extra:?}");
    }

    #[test]
    fn wrapping_keeps_every_word_and_the_width() {
        assert_eq!(wrap_lines("a b c", 3), ["a b", "c"]);
        assert_eq!(wrap_lines("abcdefg", 3), ["abc", "def", "g"]);
        assert_eq!(wrap_lines("one\r\n\r\ntwo\n", 10), ["one", "", "two"]);
        assert_eq!(wrap_lines("\tx", 10), ["    x"]);
        // Indentation is not a place to break: the long word is cut hard instead of leaving an empty line.
        assert_eq!(wrap_lines("    abcdefgh", 6), ["    ab", "cdefgh"]);
        assert_eq!(wrap_lines("", 5), [""]);
        for d in &DOCS {
            for cols in [20, 63, 84] {
                let lines = wrap_lines(d.text, cols);
                assert!(lines.iter().all(|l| l.chars().count() <= cols), "{} at {cols}", d.label);
                let squash = |s: &str| s.chars().filter(|c| !c.is_whitespace()).collect::<String>();
                assert_eq!(squash(&lines.concat()), squash(d.text), "{} at {cols}", d.label);
            }
        }
    }
}
